package com.argument.exporttrial;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.*;
import org.springframework.stereotype.Component;

/** SpreadsheetML inline strings prevent formula execution; long values use lossless LongText rows. */
@Component
public class StructuredExportWriter {
    private static final String NS="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
    public byte[] write(ObjectNode bundle,String format){try{if(format.equals("JSON"))return bundle.toPrettyString().getBytes(StandardCharsets.UTF_8);return xlsx(bundle);}catch(IOException e){throw new IllegalStateException("Export serialization failed",e);}}
    private byte[] xlsx(ObjectNode bundle)throws IOException{
        var sheets=new LinkedHashMap<String,List<ObjectNode>>();var manifest=JsonNodeFactory.instance.objectNode().put("schemaVersion",bundle.path("schemaVersion").asText()).put("exportId",bundle.path("exportId").asText()).put("createdAt",bundle.path("createdAt").asText()).put("longTextRule","@LongText references use sheet/row/field; concatenate numbered parts without separators");sheets.put("Manifest",new ArrayList<>(List.of(manifest)));
        Map<String,String> names=Map.ofEntries(Map.entry("sourceManifest","Sources"),Map.entry("textVersions","TextVersions"),Map.entry("scopes","Scopes"),Map.entry("labels","Labels"),Map.entry("relationDefinitions","RelationDefinitions"),Map.entry("elements","Elements"),Map.entry("relations","Relations"),Map.entry("participants","Participants"),Map.entry("finalVersions","FinalVersions"),Map.entry("provenance","Provenance"),Map.entry("graphs","Graphs"),Map.entry("layouts","Layouts"),Map.entry("actorDisplayNames","ActorNames"));
        names.keySet().stream().sorted().forEach(key->{var rows=new ArrayList<ObjectNode>();bundle.path(key).forEach(n->rows.add((ObjectNode)n));sheets.put(names.get(key),rows);});for(String extra:List.of("segmentationCheckpoints","agreementCalculations","segmentationSubmissions","documents","guideVersions","sourceVersions","sourceObjects","decisionReferences")){var rows=new ArrayList<ObjectNode>();bundle.path(extra).forEach(n->rows.add((ObjectNode)n));sheets.put(Character.toUpperCase(extra.charAt(0))+extra.substring(1),rows);}var longText=new ArrayList<ObjectNode>();var xml=new LinkedHashMap<String,String>();for(var entry:sheets.entrySet())xml.put(entry.getKey(),worksheet(entry.getKey(),entry.getValue(),longText));xml.put("LongText",worksheet("LongText",longText,new ArrayList<>()));
        var bytes=new ByteArrayOutputStream();try(var zip=new ZipOutputStream(bytes,StandardCharsets.UTF_8)){StringBuilder types=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/>");StringBuilder book=new StringBuilder("<workbook xmlns=\""+NS+"\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets>");StringBuilder rels=new StringBuilder("<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">");int i=0;for(var entry:xml.entrySet()){i++;types.append("<Override PartName=\"/xl/worksheets/sheet").append(i).append(".xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>");book.append("<sheet name=\"").append(entry.getKey()).append("\" sheetId=\"").append(i).append("\" r:id=\"rId").append(i).append("\"/>");rels.append("<Relationship Id=\"rId").append(i).append("\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet").append(i).append(".xml\"/>");part(zip,"xl/worksheets/sheet"+i+".xml",entry.getValue());}part(zip,"[Content_Types].xml",types+"</Types>");part(zip,"xl/workbook.xml",book+"</sheets></workbook>");part(zip,"xl/_rels/workbook.xml.rels",rels+"</Relationships>");part(zip,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");}return bytes.toByteArray();
    }
    private String worksheet(String sheet,List<ObjectNode> rows,List<ObjectNode> longText){var fields=new TreeSet<String>();rows.forEach(n->n.fieldNames().forEachRemaining(fields::add));if(fields.isEmpty())fields.add("id");if(rows.size()>1_000_000)throw new IllegalStateException("Too many spreadsheet rows");StringBuilder xml=new StringBuilder("<worksheet xmlns=\""+NS+"\"><sheetData>");xml.append("<row r=\"1\">");fields.forEach(f->cell(xml,f));xml.append("</row>");int row=1;for(var record:rows){row++;xml.append("<row r=\"").append(row).append("\">");for(String field:fields){JsonNode node=record.path(field);String value=node.isMissingNode()?"":node.isTextual()?node.asText():node.toString();if(value.length()>30000){String text=value;int part=0;for(int start=0;start<text.length();){int end=Math.min(start+30000,text.length());if(end<text.length() && Character.isHighSurrogate(text.charAt(end-1)))end--;longText.add(JsonNodeFactory.instance.objectNode().put("sheet",sheet).put("row",row).put("field",field).put("part",++part).put("text",text.substring(start,end)));start=end;}value="@LongText:"+sheet+":"+row+":"+field;}cell(xml,value);}xml.append("</row>");}return xml+"</sheetData></worksheet>";}
    private void cell(StringBuilder xml,String value){xml.append("<c t=\"inlineStr\"><is><t xml:space=\"preserve\">");value.replaceAll("_(?=x[0-9A-Fa-f]{4}_)","_x005F_").codePoints().forEach(c->{if(c=='&')xml.append("&amp;");else if(c=='<')xml.append("&lt;");else if(c=='>')xml.append("&gt;");else if(c==13)xml.append("&#13;");else if(c==9||c==10||c>=32&&c<=0xD7FF||c>=0xE000&&c<=0xFFFD||c>=0x10000&&c<=0x10FFFF)xml.appendCodePoint(c);else throw new IllegalStateException("Text contains characters forbidden in XML");});xml.append("</t></is></c>");}
    private void part(ZipOutputStream zip,String name,String text)throws IOException{zip.putNextEntry(new ZipEntry(name));zip.write(text.getBytes(StandardCharsets.UTF_8));zip.closeEntry();}
}
